package dk.jamesbabz.madkursus.service.applications;
import com.fasterxml.jackson.databind.ObjectMapper;import dk.jamesbabz.madkursus.service.models.*;import dk.jamesbabz.madkursus.service.ports.ProductTemplatePort;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;
class NutritionAdminServiceTest {
 @Test void listsMissingKnownAndKnownZeroAndPersistsProvenance(){ProductTemplatePort port=mock(ProductTemplatePort.class);dk.jamesbabz.madkursus.service.ports.RecipeTemplatePort recipes=mock(dk.jamesbabz.madkursus.service.ports.RecipeTemplatePort.class);when(recipes.search("")).thenReturn(List.of());ProductTemplate missing=template("Missing",null);ProductTemplate zero=template("Zero",nutrition("0"));ProductTemplate known=template("Known",nutrition("5"));when(port.search("",null)).thenReturn(List.of(missing,zero,known));var service=new NutritionAdminService(port,recipes,new ObjectMapper());assertThat(service.list("MISSING","")).extracting(e->e.template().name()).containsExactly("Missing");assertThat(service.list("KNOWN","")).extracting(NutritionAdminService.Entry::status).containsExactlyInAnyOrder(NutritionAdminService.Status.KNOWN_ZERO,NutritionAdminService.Status.KNOWN);NutritionData updated=new NutritionData(new BigDecimal("5.4"),new BigDecimal("100"),RecipeUnit.GRAM,"DTU", "DTU","716","2026",null,"raw");when(port.findById(missing.id())).thenReturn(Optional.of(missing));when(port.updateNutrition(missing.id(),updated)).thenReturn(template("Missing",updated));assertThat(service.update(missing.id(),updated).template().nutritionData().externalFoodId()).isEqualTo("716");verify(port).updateNutrition(missing.id(),updated);}
 private ProductTemplate template(String name,NutritionData n){return new ProductTemplate(UUID.randomUUID(),name,ProductCategory.OTHER,Unit.GRAM,InventoryTrackingMode.QUANTITY,List.of(),false,List.of(),n);}private NutritionData nutrition(String grams){return new NutritionData(new BigDecimal(grams),new BigDecimal("100"),RecipeUnit.GRAM,"test");}
}
